+
+  - do:
+      bulk:
+        refresh: true
+        index: source
+        body:
+          - '{"index": {}}'
+          - '{"baz": "quick", "a": "brown", "b": "fox"}'
+          - '{"index": {}}'
+          - '{"baz": "lazy", "a": "dog"}'
+
+  - do:
+      enrich.put_policy:
+        name: test_policy
+        body:
+          match:
+            indices: ["source*"]
+            match_field: baz
+            enrich_fields: ["a", "b"]
+
+  - do:
+      enrich.execute_policy:
+        name: test_policy
+
