+
+        @Override
+        public BytesReference sourceAsBytes() {
+            if (sourceProvider == null) {
+                readSourceBytes();
+            }
+            return sourceProvider.sourceAsBytes();
+        }
+
+        @Override
+        public List<Object> extractRawValuesWithoutCaching(String path) {
