+                reader.accept(doc, visitor);
+                this.doc = doc;
+            }
+        }
+
+        @Override
+        public BytesReference source() {
+            return visitor.source();
+        }
+
+        @Override
+        public String id() {
+            return visitor.id();
+        }
+
+        @Override
+        public String routing() {
+            return visitor.routing();
+        }
+
+        @Override
+        public Map<String, List<Object>> storedFields() {
+            return visitor.fields();
+        }
+    }
+
+}
