+                            ],
+                            "full_name": null,
+                            "email": null,
+                            "metadata": {
+                              "_reserved": true
+                            },
+                            "enabled": true%s
+                          },
+                          "%s": {
+                            "username": "%s",
+                            "roles": [
+                              %s
+                            ],
+                            "full_name": null,
+                            "email": null,
+                            "metadata": {},
+                            "enabled": true%s
+                          }
