+        level1.put("null", null);
+        a.put("level1", level1);
+        a.put("null", null);
+        // WriteField.leaf is null
+        assertFalse(new WriteField("missing.leaf", () -> a).exists());
+
+        // WriteField.leaf non-null but missing
