+            Version.CURRENT
+        );
+        allNodes = new DiscoveryNode[] { localNode };
+    }
+
+    @After
+    public void tearDown() throws Exception {
+        super.tearDown();
+        clusterService.close();
+        transportService.close();
+    }
+
+    @AfterClass
